<section class="admin-v2-page-intro"><div><span class="admin-v2-eyebrow">EDITORIAL CONTENT</span><h2>إدارة المقالات</h2><p>تحديث حالة المقال فقط؛ الصور والروابط والترجمات لا تُحذف من هذه المساحة.</p></div><form class="admin-v2-filter" method="get"><input name="q" value="<?=e($q)?>" placeholder="عنوان أو slug أو كاتب"><select name="status"><option value="">كل الحالات</option><?php foreach(['draft'=>'مسودة','review'=>'مراجعة','changes'=>'تعديلات','published'=>'منشور','archived'=>'مؤرشف'] as $key=>$label):?><option value="<?=e($key)?>" <?=$status===$key?'selected':''?>><?=e($label)?></option><?php endforeach;?></select><button class="admin-v2-button primary" type="submit">تصفية</button></form></section>
<section class="admin-v2-table-panel"><div class="admin-v2-table-wrap"><table class="admin-v2-table"><thead><tr><th>المقال</th><th>الكاتب</th><th>الحالة</th><th>التحديث</th><th>إجراء</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5"><div class="admin-v2-empty">لا توجد مقالات.</div></td></tr><?php else:foreach($rows as $row):?><tr><td><strong><?=e((string)($row['title']??'بدون عنوان'))?></strong><small><?=e((string)($row['slug']??''))?></small></td><td><?=e((string)$row['author_name'])?></td><td><span class="admin-v2-badge <?=e((string)$row['status'])?>"><?=e((string)$row['status'])?></span></td><td><?=e((string)$row['updated_at'])?></td><td><details class="admin-v2-actions"><summary>تغيير الحالة</summary><form method="post" action="/admin-v2/articles/action"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($row['id'])?>"><select name="status"><option value="draft">مسودة</option><option value="review">مراجعة</option><option value="changes">تعديلات</option><option value="published">منشور</option></select><button class="admin-v2-small-button" type="submit">حفظ</button></form></details></td></tr><?php endforeach;endif;?></tbody></table></div></section>
